antiPatterns.code:
// Avoid: Generic fallback
<AvatarFallback>Avatar</AvatarFallback>

// Prefer: Use initials or name
<AvatarFallback>JD</AvatarFallback>

// Avoid: Avatar for company logos
<Avatar>
  <AvatarImage src="/logo.png" alt="Company" />
</Avatar>

// Prefer: Use appropriate image component
<img src="/logo.png" alt="Company" className="rounded" />
